using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;using TMPro;using EternalSteam.OpenWorld;
public static class PolishHudGroups{
public static string Main(){if(EditorApplication.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean edit mode required");var setup=EditorSceneManager.GetSceneManagerSetup();try{foreach(var n in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+n+".unity");var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();var g=h.Groups;var objective=h.Sections.FirstOrDefault(s=>s.Id=="first-loop").Body;
if(objective!=null){var r=(RectTransform)objective.transform;r.SetParent(g.ConstructionSlides.Single(s=>s.Direction==Vector2.down).Host,false);r.anchorMin=Vector2.zero;r.anchorMax=new Vector2(1,0);r.pivot=new Vector2(.5f,0);r.offsetMin=new Vector2(320,304);r.offsetMax=new Vector2(-304,362);}
foreach(var id in new[]{"date","remaining"}){var t=h.Texts.Single(b=>b.Id==id).View;int i=Array.IndexOf(h.Layout.Texts,t);if(i>=0)h.Layout.FontSizes[i]=18;t.fontSize=18;t.enableAutoSizing=false;}
var power=h.GetComponentsInChildren<RectTransform>(true).Single(r=>r.name=="PowerSummary");power.anchorMin=power.anchorMax=power.pivot=Vector2.one;power.anchoredPosition=new Vector2(-340,-16);power.sizeDelta=new Vector2(280,60);
EditorUtility.SetDirty(h.Layout);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}return "Time font rules and group ownership saved";}}
